const scoreEl = document.getElementById("score");
const statusEl = document.getElementById("status");

const roads = [
  { x: 0, y: 115, w: 720, h: 70 },
  { x: 0, y: 335, w: 720, h: 70 },
  { x: 145, y: 0, w: 70, h: 520 },
  { x: 505, y: 0, w: 70, h: 520 }
];

const intersections = [
  { x: 145, y: 115, w: 70, h: 70, phase: 0 },
  { x: 505, y: 115, w: 70, h: 70, phase: 1 },
  { x: 145, y: 335, w: 70, h: 70, phase: 1 },
  { x: 505, y: 335, w: 70, h: 70, phase: 0 }
];

const deliveries = [
  { x: 70, y: 75 },
  { x: 635, y: 75 },
  { x: 70, y: 445 },
  { x: 635, y: 445 },
  { x: 350, y: 260 }
];

let bike, keys, started, over, packages, score, timeLeft, lastTime, lightTimer, currentTarget;

function reset() {
  bike = { x: 180, y: 370, r: 12, speed: 190 };
  keys = {};
  started = false;
  over = false;
  packages = 0;
  score = 0;
  timeLeft = 60;
  lastTime = 0;
  lightTimer = 0;
  currentTarget = 0;
  updateHUD("Ready");
  draw();
}

