    ctx.fillStyle = idx < currentTarget ? "#64748b" : idx === currentTarget ? "#facc15" : "#94a3b8";
    ctx.beginPath();
    ctx.arc(d.x, d.y, idx === currentTarget ? 18 : 11, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#111827";
    ctx.font = "bold 14px system-ui";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(idx + 1, d.x, d.y);
  });
}

function drawBike() {
  ctx.save();
  ctx.translate(bike.x, bike.y);
  ctx.fillStyle = "#38bdf8";
  ctx.beginPath();
  ctx.arc(0, 0, bike.r, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = "#e0f2fe";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-14, 10);
  ctx.lineTo(14, 10);
  ctx.moveTo(-8, -8);
  ctx.lineTo(8, 8);
  ctx.stroke();

  ctx.restore();
}

function drawOverlay(text, sub) {
  ctx.fillStyle = "rgba(15,23,42,.82)";
  ctx.fillRect(85, 120, 550, 260);
  ctx.fillStyle = "white";
  ctx.textAlign = "center";
  ctx.font = "bold 34px system-ui";
  ctx.fillText(text, 360, 195);
  ctx.font = "18px system-ui";
  ctx.fillText(sub, 360, 238);
  ctx.fillText("Avoid red lights. Deliver packages in order.", 360, 270);
  ctx.fillText("Arrow keys, WASD, or touch buttons.", 360, 302);
}

function draw() {
  ctx.clearRect(0, 0, 720, 520);
  drawBlocks();
  drawRoads();
  drawLights();
  drawDeliveries();
  drawBike();

  if (!started) drawOverlay("Ready to ride?", "Press Start to begin");
  if (over) drawOverlay(packages >= 5 ? "Route complete!" : "Shift over", "Final score: " + score);
}

function startGame() {
  if (over) reset();
  started = true;
  lastTime = 0;
  updateHUD("Go!");
  requestAnimationFrame(tick);
}

document.getElementById("start").onclick = startGame;
document.getElementById("restart").onclick = () => { reset(); startGame(); };

document.querySelectorAll("[data-dir]").forEach(btn => {
  const dir = btn.dataset.dir;
  btn.addEventListener("pointerdown", e => {
    e.preventDefault();
    keys[dir] = true;
  });
  btn.addEventListener("pointerup", () => keys[dir] = false);
  btn.addEventListener("pointerleave", () => keys[dir] = false);
});

window.addEventListener("keydown", e => {
  const map = {
    ArrowLeft: "left", a: "left", A: "left",
    ArrowRight: "right", d: "right", D: "right",
    ArrowUp: "up", w: "up", W: "up",
    ArrowDown: "down", s: "down", S: "down"
  };
  if (map[e.key]) {
    e.preventDefault();
    keys[map[e.key]] = true;
  }
  if (e.key === "Enter" || e.key === " ") startGame();
});

window.addEventListener("keyup", e => {
  const map = {
    ArrowLeft: "left", a: "left", A: "left",
    ArrowRight: "right", d: "right", D: "right",
    ArrowUp: "up", w: "up", W: "up",
    ArrowDown: "down", s: "down", S: "down"
  };
  if (map[e.key]) keys[map[e.key]] = false;
});

reset();
</script>
