    over = true;
    score += Math.ceil(timeLeft) * 5;
    updateHUD("All delivered");
  }

  if (timeLeft <= 0) {
    timeLeft = 0;
    over = true;
    updateHUD("Shift over");
  }

  draw();
  if (!over) requestAnimationFrame(tick);
