function drawBlocks() {
  ctx.fillStyle = "#334155";
  const blocks = [
    [20, 20, 100, 70], [245, 25, 220, 70], [600, 20, 90, 70],
    [245, 215, 220, 90], [20, 215, 100, 90], [600, 215, 90, 90],
    [20, 430, 100, 60], [245, 430, 220, 60], [600, 430, 90, 60]
  ];

  blocks.forEach(b => {
    ctx.fillStyle = "#334155";
    ctx.fillRect(...b);
    ctx.fillStyle = "#475569";
    ctx.fillRect(b[0] + 12, b[1] + 12, b[2] - 24, 14);
    ctx.fillRect(b[0] + 12, b[1] + 36, b[2] - 24, 10);
  });
}

function drawRoads() {
  ctx.fillStyle = "#1d2430";
  roads.forEach(r => ctx.fillRect(r.x, r.y, r.w, r.h));

  ctx.strokeStyle = "#e7d86b";
  ctx.setLineDash([18, 18]);
  ctx.lineWidth = 3;

  ctx.beginPath();
  ctx.moveTo(0, 150);
  ctx.lineTo(720, 150);
  ctx.moveTo(0, 370);
  ctx.lineTo(720, 370);
  ctx.moveTo(180, 0);
  ctx.lineTo(180, 520);
  ctx.moveTo(540, 0);
  ctx.lineTo(540, 520);
  ctx.stroke();

  ctx.setLineDash([]);
}

function drawCrosswalks() {
  ctx.strokeStyle = "rgba(255,255,255,.28)";
  ctx.lineWidth = 2;

  for (const i of intersections) {
    for (let k = 0; k < 5; k++) {
      ctx.beginPath();
      ctx.moveTo(i.x + 6 + k * 13, i.y - 8);
      ctx.lineTo(i.x + 6 + k * 13, i.y + 2);
      ctx.moveTo(i.x + 6 + k * 13, i.y + i.h - 2);
      ctx.lineTo(i.x + 6 + k * 13, i.y + i.h + 8);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(i.x - 8, i.y + 6 + k * 13);
      ctx.lineTo(i.x + 2, i.y + 6 + k * 13);
      ctx.moveTo(i.x + i.w - 2, i.y + 6 + k * 13);
      ctx.lineTo(i.x + i.w + 8, i.y + 6 + k * 13);
      ctx.stroke();
    }
  }
}

function drawLights() {
  intersections.forEach(i => {
    const horizontalGreen = i.phase === 0;

    ctx.fillStyle = "rgba(255,255,255,.08)";
    ctx.fillRect(i.x, i.y, i.w, i.h);

    ctx.fillStyle = horizontalGreen ? "#22c55e" : "#ef4444";
    ctx.beginPath();
    ctx.arc(i.x + 20, i.y + 15, 8, 0, Math.PI * 2);
    ctx.arc(i.x + 50, i.y + 55, 8, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = horizontalGreen ? "#ef4444" : "#22c55e";
    ctx.beginPath();
    ctx.arc(i.x + 55, i.y + 20, 8, 0, Math.PI * 2);
    ctx.arc(i.x + 15, i.y + 50, 8, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "rgba(255,255,255,.75)";
    ctx.font = "bold 11px system-ui";
    ctx.textAlign = "center";
    ctx.fillText(horizontalGreen ? "← →" : "↑ ↓", i.x + 35, i.y + 39);
  });
}

function drawCars() {
  for (const car of cars) {
    ctx.fillStyle = car.color;
    ctx.fillRect(car.x, car.y, car.w, car.h);

    ctx.fillStyle = "rgba(255,255,255,.8)";
    if (car.w > car.h) {
      ctx.fillRect(car.x + 8, car.y + 4, 10, 5);
      ctx.fillRect(car.x + 24, car.y + 4, 10, 5);
      ctx.fillStyle = "#111827";
      ctx.fillRect(car.x + 6, car.y + car.h - 2, 7, 3);
      ctx.fillRect(car.x + car.w - 13, car.y + car.h - 2, 7, 3);
    } else {
      ctx.fillRect(car.x + 4, car.y + 8, 5, 10);
      ctx.fillRect(car.x + 4, car.y + 24, 5, 10);
      ctx.fillStyle = "#111827";
      ctx.fillRect(car.x + car.w - 2, car.y + 6, 3, 7);
      ctx.fillRect(car.x + car.w - 2, car.y + car.h - 13, 3, 7);
    }
  }
}

function drawDeliveries() {
  deliveries.forEach((d, idx) => {
    ctx.fillStyle = idx < currentTarget ? "#64748b" : idx === currentTarget ? "#facc15" : "#94a3b8";
    ctx.beginPath();
    ctx.arc(d.x, d.y, idx === currentTarget ? 18 : 11, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#111827";
    ctx.font = "bold 14px system-ui";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(idx + 1, d.x, d.y);
  });
}

function drawBike() {
  ctx.save();
  ctx.translate(bike.x, bike.y);

  if (crashCooldown > 0) {
    ctx.globalAlpha = Math.sin(Date.now() / 70) > 0 ? 0.45 : 1;
  }

  ctx.fillStyle = "#38bdf8";
  ctx.beginPath();
  ctx.arc(0, 0, bike.r, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = "#e0f2fe";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-14, 10);
  ctx.lineTo(14, 10);
  ctx.moveTo(-8, -8);
  ctx.lineTo(8, 8);
  ctx.stroke();

  ctx.restore();
}

function drawOverlay(text, sub) {
  ctx.fillStyle = "rgba(15,23,42,.84)";
  ctx.fillRect(85, 110, 550, 285);

  ctx.fillStyle = "white";
  ctx.textAlign = "center";
  ctx.font = "bold 34px system-ui";
  ctx.fillText(text, 360, 180);

  ctx.font = "18px system-ui";
  ctx.fillText(sub, 360, 224);
  ctx.fillText("Deliver packages in order.", 360, 258);
  ctx.fillText("Cars obey the lights. You should too.", 360, 288);
  ctx.fillText("Car hit: -8 seconds and -40 score.", 360, 318);
}

function draw() {
  ctx.clearRect(0, 0, 720, 520);
  drawBlocks();
  drawRoads();
  drawCrosswalks();
  drawLights();
  drawDeliveries();
  drawCars();
  drawBike();

  if (!started) drawOverlay("Ready to ride?", "Press Start, Enter, or Space");
  if (over) drawOverlay(packages >= 5 ? "Route complete!" : "Shift over", "Final score: " + score);
}

function startGame() {
  if (over) reset();
  if (started) return;
  started = true;
  lastTime = 0;
  setStatus("Go!", 0.7);
  requestAnimationFrame(tick);
}

document.getElementById("start").onclick = startGame;
document.getElementById("restart").onclick = () => {
  reset();
  startGame();
};

