<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

const pkgEl = document.getElementById("pkg");
const timeEl = document.getElementById("time");
const scoreEl = document.getElementById("score");
const bestEl = document.getElementById("best");

const BEST_KEY = "blockBikeCourierBestV2";

const roads = [
  { x: 0, y: 110, w: 720, h: 70, type: "h", lane: 145 },
  { x: 0, y: 320, w: 720, h: 70, type: "h", lane: 355 },
  { x: 145, y: 0, w: 70, h: 500, type: "v", lane: 180 },
  { x: 505, y: 0, w: 70, h: 500, type: "v", lane: 540 }
];

const intersections = [
  { x: 145, y: 110, w: 70, h: 70, phase: 0 },
  { x: 505, y: 110, w: 70, h: 70, phase: 1 },
  { x: 145, y: 320, w: 70, h: 70, phase: 1 },
  { x: 505, y: 320, w: 70, h: 70, phase: 0 }
];

const baseDeliveries = [
  { x: 70, y: 72 },
  { x: 635, y: 72 },
  { x: 70, y: 430 },
  { x: 635, y: 430 },
  { x: 350, y: 250 }
];

let deliveries;
let bike, keys, started, over, packages, score, timeLeft, elapsed, lastTime, lightTimer, currentTarget;
let cars, crashCooldown, flashTimer, shakeTimer, floatingTexts, statusText, statusTimer;
let bestRun;

function loadBest() {
  try {
    bestRun = JSON.parse(localStorage.getItem(BEST_KEY)) || null;
  } catch {
    bestRun = null;
  }
  updateBestHUD();
}

function saveBestIfNeeded() {
  if (packages < deliveries.length) return;

  const medal = getMedal(score, elapsed);
  const next = {
    score,
    time: Number(elapsed.toFixed(2)),
    medal
  };

  if (!bestRun || score > bestRun.score || (score === bestRun.score && elapsed < bestRun.time)) {
    bestRun = next;
    localStorage.setItem(BEST_KEY, JSON.stringify(bestRun));
  }

  updateBestHUD();
}

function updateBestHUD() {
  if (!bestRun) {
    bestEl.textContent = "—";
  } else {
    bestEl.textContent = `${bestRun.medal} ${bestRun.score}`;
  }
}

function getMedal(finalScore, runTime) {
  if (finalScore >= 900 && runTime <= 42) return "Gold";
  if (finalScore >= 750 && runTime <= 50) return "Silver";
  if (finalScore >= 600) return "Bronze";
  return "Finish";
}

function shuffleDeliveries() {
  deliveries = baseDeliveries.map(d => ({ ...d }));

  for (let i = deliveries.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [deliveries[i], deliveries[j]] = [deliveries[j], deliveries[i]];
  }
}

function reset() {
  shuffleDeliveries();

  bike = { x: 180, y: 355, r: 13, speed: 195 };
  keys = {};
  started = false;
  over = false;
  packages = 0;
  score = 0;
  timeLeft = 60;
  elapsed = 0;
  lastTime = 0;
  lightTimer = 0;
  currentTarget = 0;
  crashCooldown = 0;
  flashTimer = 0;
  shakeTimer = 0;
  floatingTexts = [];
  statusText = "Ready";
  statusTimer = 0;

  cars = [
    { x: -80, y: 124, w: 46, h: 24, dir: 1, speed: 105, road: "hTop", color: "#f97316" },
    { x: 790, y: 164, w: 46, h: 24, dir: -1, speed: 90, road: "hTop", color: "#a78bfa" },
    { x: -180, y: 334, w: 46, h: 24, dir: 1, speed: 115, road: "hBottom", color: "#22c55e" },
    { x: 850, y: 374, w: 46, h: 24, dir: -1, speed: 100, road: "hBottom", color: "#38bdf8" },
    { x: 154, y: -90, w: 24, h: 46, dir: 1, speed: 95, road: "vLeft", color: "#facc15" },
    { x: 194, y: 610, w: 24, h: 46, dir: -1, speed: 85, road: "vLeft", color: "#fb7185" },
    { x: 514, y: -160, w: 24, h: 46, dir: 1, speed: 110, road: "vRight", color: "#60a5fa" },
