  btn.addEventListener("pointerup", e => {
    e.preventDefault();
    keys[dir] = false;
  }, { passive: false });

  btn.addEventListener("pointerleave", () => keys[dir] = false);
  btn.addEventListener("pointercancel", () => keys[dir] = false);
