    ArrowUp: "up", w: "up", W: "up",
    ArrowDown: "down", s: "down", S: "down"
  };

  if (map[e.key]) keys[map[e.key]] = false;
});

window.addEventListener("blur", () => {
  keys = {};
});

loadBest();
reset();
</script>
